const response = $input.first().json;

const outputText = response.output
  ?.flatMap((outputItem) => outputItem.content ?? [])
  .find((contentItem) => contentItem.type === 'output_text')
  ?.text;

if (!outputText) {
  throw new Error('OpenAI did not return an output_text value.');
}

const cleanedText = outputText
  .replace(/^```json\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let analysis;

try {
  analysis = JSON.parse(cleanedText);
} catch (error) {
  throw new Error(`OpenAI returned invalid JSON: ${error.message}`);
}

return [
  {
    json: {
      ai_analysis: analysis,
    },
  },
];

const items = $input.all();

return items.map((item) => {
  const outputText = item.json.output
    ?.flatMap((message) => message.content || [])
    .find((content) => content.type === "output_text")
    ?.text;

  if (!outputText) {
    throw new Error("The Evaluate Job Fit node returned no text.");
  }

  const cleanedText = outputText
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  let evaluation;

  try {
    evaluation = JSON.parse(cleanedText);
  } catch (error) {
    throw new Error(
      `The job-fit response was not valid JSON: ${error.message}`
    );
  }

  return {
    json: {
      job_fit_evaluation: evaluation
    }
  };
});
